import{_ as e}from"./chunks/e2fd4e324e125aac74c9.DWECbjXu.js";import{_ as r,C as o,o as i,c as l,j as a,a as n,E as s,a5 as m}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"创作者经济是一个巨大的庞氏骗局","description":"","frontmatter":{"title":"创作者经济是一个巨大的庞氏骗局","originalTitle":"The Creator Economy Is A Giant Ponzi Scheme","date":"2024-08-24","originalUrl":"https://thedankoe.com/letters/the-creator-economy-is-a-giant-ponzi-scheme/","minutes":25,"sourceHash":"031e153031528aa366112663b24de71860beb306bb157ea610c3e51b1d116214","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-creator-economy-is-a-giant-ponzi-scheme/"}]]},"headers":[],"relativePath":"letters/the-creator-economy-is-a-giant-ponzi-scheme.md","filePath":"letters/the-creator-economy-is-a-giant-ponzi-scheme.md"}'),h={name:"letters/the-creator-economy-is-a-giant-ponzi-scheme.md"};function c(d,p,g,f,u,_){const t=o("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=a("h1",{id:"创作者经济是一个巨大的庞氏骗局",tabindex:"-1"},[n("创作者经济是一个巨大的庞氏骗局 "),a("a",{class:"header-anchor",href:"#创作者经济是一个巨大的庞氏骗局","aria-label":'Permalink to "创作者经济是一个巨大的庞氏骗局"'},"​")],-1)),s(t),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/ROEBdWJhYto?si=YZEUpfqtSkY3s8NE" target="_blank" rel="noreferrer">观看原文视频</a></p><p>有些事情让我相当恼火，这就是其中之一。</p><p>一个新手开始了他的创作者之旅。</p><p>他们学习写作、营销、品牌打造，以及其他与自己手艺配套的技能，让自己能成为一人企业——因为作为创作者，你需要成为一个<em>专精的通才</em>。</p><p>换句话说，你需要对所有数字业务技能有一个整体的理解，同时还要在你每天都热爱做的那一件事上足够专精。在很多事情上做得好，在一件事上做得出色，因为那种整体理解正是<em>让你在那一件事上做到出色的原因</em>。</p><p><img src="'+e+'" alt=""></p><p>新手创作者想开始赚钱。这很合理。想卖自己的产品从而不再替别人卖东西，这没有什么错。</p><p>现在，棘手的部分来了：</p><p>新手创作者想用自己学到的技能帮助其他创作者。营销、销售、品牌、写作，不管是什么。</p><p>他们想用自己在这个商业模式中积累了经验的技能，去帮助那些正在这方面积累经验的其他创作者。这说得通。</p><p>让我恼火的地方是，有些人把这称为庞氏骗局。</p><p>他们不懂商业，所以只能看到事情的表面，并把它简化归结为这个说法。</p><p>“你只不过是一个帮创作者变成创作者的创作者。”</p><p>“你只不过是一个教教练变成教练的教练。”</p><p>我明白，表面上看确实不太好，但如果你不肯再深入看一看到底发生了什么，生活中其他的一切也都是这样。</p><p>这群思维狭隘的人首先似乎不明白的是，什么是庞氏骗局。他们似乎只是觉得，帮助别人做你已经做过的事情（也就是你唯一真正有资格做的事情）是坏事，所以他们就管它叫庞氏骗局。</p><p>庞氏骗局，按定义来说，是一种金融欺诈，用新投资者的资金来支付早期投资者的回报，而不是通过合法经营业务所赚取的利润。</p><p>创作者的生意根本不是这个样子。稍后我会处理更多的反对意见，但你需要理解的是，创作者的生意就是一种生意。创作者可以是一个人经营，也可以带团队经营。按照那些思维狭隘者的逻辑，整个B2B商业界都是庞氏骗局，因为他们都在用自己学到的技能互相帮助彼此的生意。</p><p>庞氏骗局的特征是依赖、欺骗和操控。而一般意义上的商业，尤其是创作者模式，其特征是<em>独立性</em>、说服力和自主选择。没有人强迫你去听谁的话或买谁的产品。仅仅因为它不适合你，并不意味着它对另一个人来说没有价值、不值得付费。</p><p>现在，让我们从进化论的角度来看这个问题。</p><p>有两种等级结构：</p><p><strong>统治型等级结构</strong>——通过武力、权力、控制和支配来维持结构的系统。这种等级结构内部的关系通常以强制、自上而下的权威和恐惧为特征。</p><p>这类例子包括大多数企业结构、动物王国中类似阿尔法雄性猿类优先获得食物和交配权的现象，以及某些政治结构，比如独裁统治。</p><p>等级结构反映在一切事物之中。在生物学层面上，癌细胞可以开始建立一种统治型等级结构，除非它被重新整合进身体的自然等级体系中。</p><p>庞氏骗局并不完全等同于统治型等级结构，但两者属于同一类。</p><p>那些声称创作者经济是庞氏骗局的人，往往正是被困在某种统治型等级结构之中。这很可悲，因为他们在向自己封闭了摆脱困境的少数出路之一。</p><p><strong>自我实现型等级结构</strong>——受马斯洛需求层次理论等理论的启发，其结构旨在支持成员的成长、发展和自我实现。这种等级结构中的领导力旨在赋能个体，而不是控制个体。</p><p>这正是创新型初创企业、创作者经济，以及进步教育（同样也是创作者经济，教授人们关于自己的技能和兴趣）发挥作用的地方。</p><p>创作者并不控制你做什么。他们不过是媒体渠道而已。他们分发信息。如果你觉得这是坏事，去看看Tyler The Creator关于网络霸凌的那条推文，然后关掉你的屏幕吧。</p><p>创作者经济的核心特征是<em>提升自己、也提升他人</em>。</p><p>价值的交换。</p><p>解决问题，并分发解决方案。</p><p>一个创作者帮助另一个创作者，完全合乎情理，甚至可以说是你能做的最有成就感的事情之一。</p><p>考虑到独立性、高技能天花板、高收入上限、高能动性，以及一切让生活值得过下去的因素，在我看来，成为创作者就是未来的方向（许多有影响力的人也都预言创作者将是未来工作的形态）。</p><h3 id="以下是你在这篇文章中可以期待看到的内容" tabindex="-1">以下是你在这篇文章中可以期待看到的内容： <a class="header-anchor" href="#以下是你在这篇文章中可以期待看到的内容" aria-label="Permalink to &quot;以下是你在这篇文章中可以期待看到的内容：&quot;">​</a></h3><ul><li>为什么C2C（创作者对创作者）市场是全新的、奇特的，正是你一直在等待的机会（因为你对其他一切总是“太晚了”）。</li><li>我被人视为权威的秘密武器，让你能够克服冒名顶替综合症，不再质疑自己做的每一件事。</li><li>作为创作者开启一人企业的最佳路径。如何起步，要学哪些技能，卖什么产品。</li></ul><p>这是我最喜欢写的一类文章。</p><p>我喜欢把论点撕开来分析。</p><h2 id="c2c市场" tabindex="-1">C2C市场 <a class="header-anchor" href="#c2c市场" aria-label="Permalink to &quot;C2C市场&quot;">​</a></h2><p>“内容创作者”是一种商业模式。</p><p>也就是说，一个创作者帮助其他创作者，本质上就是一家企业在帮助另一家企业。</p><p>外面有海量的创作者。他们中的大多数都不懂商业。很明显，其他创作者——那些按照别人一直教导的方式学会了可市场化技能的人——会想去帮助并教导他们，这不难理解。</p><p>按照那些思维狭隘者的标准，他们其实是在说整个B2B市场都是庞氏骗局。</p><p>是啊……这有点牵强了。</p><p>他们没意识到的另一件事是，创作者不仅仅是一人企业。创作者可以拥有小团队或大团队。他们就是企业。他们只是使用社交媒体，把自己公开展示出来，通过把自己是谁展示在互联网上来创造更多生意。</p><p>在我看来，创作者是那些想以自己喜欢的事情为生的人，他们终于意识到，商业不过是一种合法的结构，<em>用来</em>做你想做的事并因此获得报酬。</p><p>奇怪的地方在于，创作者这种模式实在太新了。创作者<em>同时</em>既是企业又是消费者。也就是说，他们向其他创作者购买东西来学习（因为提供教育和课程的正是这些人），同时又用自己学到的东西经营自己的生意。创作者正处在B2B和B2C这两个圆圈重叠的中心地带，而这条界线每一天都在变得更加模糊。</p><p>人们把这称为庞氏骗局的原因，是他们还不理解这种模式。这不是社会中的正常部分。不管你作为创作者赚多少钱，婴儿潮那一代人还是会告诉你“去找份正经工作”。他们仍然认为网络上赚的钱是某种虚构的货币，除非你在某种本该由机器人来做、最终也会由机器人来做的体力劳动中累断腰，否则那些钱都不算数。</p><p>人们把创作者经济称为庞氏骗局，恰恰更是一个信号，说明这个领域仍有机会，你依然是这场盛宴的早期参与者。</p><p>创作者对创作者（Creator2Creator）市场每天都在增长和蓬勃发展。</p><p>创作者作为一种生意，必须学习如此多的技能，并涉足几乎任何可以想象到的兴趣领域。所以当他们去教授那件事，而学的人也能借此成为创作者（因为创作者可以围绕任何兴趣建立受众），那么我理解这为什么会被视为不正当的事情。但从这个意义上说，网上每个人都是创作者，都在直接或间接地教自己的受众如何成为创作者。所以即便这真是庞氏骗局，它也是现实，而带着这种悲观心态，你的生活也不会好过多少。</p><p>这说得通，但那些正在用刚学到的技能（比如内容、品牌或营销）帮助新手创作者的创作者呢？</p><p>这总该是庞氏骗局了吧？</p><p>那么，如果那个新手创作者其实是一位已经有一定规模的企业主，只是不懂这些东西呢？企业当初为什么要雇人来做内容、品牌和营销？</p><p>Alex Hormozi为什么会雇一个之前没有任何客户或经验的代笔人，在Twitter上为他写文章？这算庞氏骗局吗？Alex并不是一个Twitter创作者，但在那个语境下他只是个新手，所以他为帮助付了钱，因为他明白这其中的价值。</p><p>语境，语境，还是语境。</p><p>我曾帮助过年营收8位数的电商CEO以创作者身份起步。你会惊讶于他们对这个领域了解得有多少。</p><p>如果你在SkillShare或Udemy上（由创作者制作）购买一门课程来学习邮件营销，那算是庞氏骗局吗？那么当你向一位公开的创作者学习——这个人真正取得过成果——的时候，你为什么不用同样的心态去看待呢？如果一个人教邮件营销，他自己就能靠邮件列表获得客户，向这样的人学习，难道不比依赖SkillShare或Udemy来分发课程更好吗？这不正是邮件营销的意义所在吗？为什么你要偏偏为自己选一个结果更差的方式，就因为教这项技能的人是从公开的、真实世界的经验出发教的？任何人都可以做一门课程，但因为社交媒体上的创作者本身就是一门生意，他们才是真正有验证过成果的人。</p><p>那么，作为一个刚学到技能的新创作者，用这些技能换钱去帮助别人，这道德吗？</p><p>如果你的答案是不道德，那就把这种心态套用到其他赚钱方式上去看看。</p><p>自由职业者是怎么获得经验的？不是靠学习，而是靠帮客户做事，即便自己做得很糟糕，往往还只能换来极少的报酬。你必须先经历“做得很差”的阶段，这可能会惹恼一些人。没关系。欢迎来到商业世界。</p><p>这件事美好的地方在于，有一种东西叫退款。如果自由职业者交不出活，他们就把钱退回去。祝你在庞氏骗局里能顺利拿回你的钱。创作者经济也有自然的制衡机制。如果你搞砸了，最好相信一定会有人把这事发出来，或者因此攻击你。你可以当个骗子，但当不了多久。群众会追着你不放。</p><p>顺便说一句，我说这一切，是为了打破你的自我限制信念，好让你终于能在成为创作者这件事上采取行动。我可以向你保证，只要你认真想清楚，大多数其他赚钱的选择都不如这条路好。</p><p>最后一种情况，如果这个创作者才刚刚起步，就向另一个想要<em>成为</em>创作者的人收费呢？</p><p>在我看来，没有比刚刚新鲜达成这个目标的人更适合向其学习的了。而处在购买这一端的人，同样拥有<em>选择权</em>——他可以选择向那个人学习，也可以选择购买他所提供的东西。</p><p>而且，由于创作者经济如此之新，市面上存在大量的教育培训也就说得通了。供求关系嘛。人们<em>想</em>成为创作者，因为潜意识里他们知道这正是未来工作的方向。</p><p>在这种情况下，唯一的“骗局”就是你缺乏独立思考的能力。</p><p>顺便说一句，我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学</a>（Digital Economics）中教你如何成为一名创作者（实际上，我只是教你当今商业所需的每一项现代技能，但如果你学完后想称自己为创作者，请便）。</p><h2 id="赢得尊重的秘密武器" tabindex="-1">赢得尊重的秘密武器 <a class="header-anchor" href="#赢得尊重的秘密武器" aria-label="Permalink to &quot;赢得尊重的秘密武器&quot;">​</a></h2><p>说了这么多，其实就是想说：</p><p>我可能改变不了那些不想被改变的人的想法。</p><p>这就像试图说服一个铁杆民主党人（或共和党人）变成共和党人（或民主党人）一样。在面对更好的论点时瞬间放下自己的信念，这是一种极其罕见但非常有价值的品质。大多数人做不到，因为这意味着他们必须改变。如果人们不得不停止把任何新机会视为骗局或庞氏骗局，他们就必须切实做点什么，而不是无所事事地沉溺在自己的悲惨境地中。他们将失去廉价多巴胺的来源：在网上当喷子。</p><p>我想帮助那些愿意接受帮助的人。</p><p>我想把赢得尊重并在做同样事情时赚得更多的秘密，告诉给有志于成为以及已经成为创作者的人。</p><p>我是一名写作者。</p><p>我教人们如何写作。</p><p>有些人会说这有点怪，但正如我所提到的，除了你正在做且有经验的事情之外，你还能更有资格教什么呢？</p><p>现在，变得棘手的地方在于，我也是一名创作者。</p><p>所以，当我教写作时，从技术上讲，我也在教人们如何成为一名创作者。</p><p>我是一个使用社交媒体的写作者（因为作为一名写作者、设计师、音乐家或任何职业，不用社交媒体多少有点蠢，因为媒体是你吸引受众关注你作品的方式（这样你才能真正获得报酬），而社交媒体就是当下的主流媒体），所以这让别人把我视为一个“创作者”。</p><p>换句话说，如果你：</p><ol><li>真的想靠做自己喜欢的事情谋生</li><li>想用你正在做的事情去教导或帮助他人（因为你有资格这么做，而且这是一个完全有效且具有影响力的商业模式）</li></ol><p>你就有被蠢货视为搞“庞氏骗局”的风险。</p><p>避免这种情况的秘诀是理解定位。</p><p>说“我帮助人们成为创作者”并不是最优解。</p><p>更优的说法是“我教写作，这样你就能吸引人们关注你的作品。”</p><p>（顺便说一句，我现在并不是在戴上营销人员的帽子说话，这些也不会是你进行自我定位的<em>最佳</em>方式。）</p><p>作为一个专门指导教练的教练，也不是最优解。</p><p>更优的做法是拥有一个面向服务型企业的线索生成系统，并使你的内容偏向于吸引你想帮助的那些教练。</p><p>你可以教其他创作者和/或想成为创作者的人。</p><p>这并没有什么问题，因为从技术上讲，社交媒体上任何有业务的人（这涉及<em>很多人</em>，包括大部分的B2B市场）都是创作者。</p><p>你只需把自己定位成一个通过教X来帮助别人获得Y收益的人。</p><p>字面上，我并不教创作者如何成为更好的创作者，因为那没多大说服力。</p><p>我教人们如何写作以吸引人们关注他们的作品。当我教这个的时候，我是在社交媒体上教的，因为那是写作者最有效的使用媒介。如果我用其他方式教，那反而是在害他们。</p><p>如果你想教营销、品牌或内容创作……那就教给你想教的任何人。你不要明确地说帮助人们成为创作者。你要教他们一项能解决生活问题、帮助他们实现理想生活方式的技能，然后仅仅因为当下工作和商业的环境，他们自然就成了创作者。</p><p>所以，如果你想被认为有价值，那就改变你对自己所提供价值的定位方式。</p><h2 id="如何开始你的一人企业" tabindex="-1">如何开始你的一人企业 <a class="header-anchor" href="#如何开始你的一人企业" aria-label="Permalink to &quot;如何开始你的一人企业&quot;">​</a></h2><p>那些不理解创作者模式的人常给的另一条建议是：</p><p>“你应该先创办一个<em>真正的</em>企业。然后再去搞那些创作者的东西。”</p><p>我懂，我真的懂，但听听你自己在说什么。</p><p>你的意思是，我不<em>应该</em>利用最好的<em>为</em>企业带来流量的方法之一，就为了去受你那些开发信、陌生电访和付费广告的折磨？这对新手来说可不太友好，不是吗？</p><p>我明白你要捍卫自己的身份认同，因为你的商业思维是靠老一代战术培养出来的，但现在有更好、更容易上手的做事方式。</p><p>科技已经允许人们建立单人媒体公司，并借此过上优渥的生活，吸引让老一辈嫉妒的受众，而这一切几乎都是零成本，全靠在社交媒体上写作。</p><p>现在成为一名创作者的好处很难用一份清单全部概括，但我会试一试。</p><ol><li>你被迫学习运营现代企业所需的所有技能。得益于各种课程、教程以及容易获取的实践工具，现在做这件事比以往任何时候都容易。</li><li>你建立了受众群体，也就是社交资本，所以当你想建立一家初创公司或你梦寐以求的企业时，你不需要个人资本或风险投资。你的应用有了用户，产品有了客户。</li><li>你拥有了超越受众的网络。为了满足需求，你几乎可以在互联网上联系到任何人。如果你有1万名粉丝，而关注他们的每个人都有500-1000名粉丝，关注这500-1000人的人也是如此，那你实际上就拥有了一个是你受众10倍的人脉网络。（当然，你显然不需要大量的粉丝也能谋生）。</li><li>你可以做你喜欢的事情，吸引志同道合的人，向新朋友展示你的技能和兴趣，并创造一个你有意义、且每天都乐在其中的商业模式，哪怕它有时也会很艰难。</li><li>因为你唯一的杠杆是写作和打造产品或服务，所以你想缩减多少工作时间就能缩减多少。如果写30分钟就能让我的受众增长，且我把他们导向一个优秀的产品，从技术上讲，我不需要工作更长时间——特别是如果我写30分钟带来的流量，比别人花8小时写一本无人问津的书还要多。</li></ol><p>这个问题目前就先说到这儿。</p><p>你该如何真正开始呢？</p><h3 id="_1-先开始-再学习" tabindex="-1">1) 先开始，再学习 <a class="header-anchor" href="#_1-先开始-再学习" aria-label="Permalink to &quot;1) 先开始，再学习&quot;">​</a></h3><p>最好的学习方式<em>不是</em>一门接一门地上课，直到你发现自己陷入了“教程地狱”，什么都没做出来，没有结果，也没有钱。</p><p>最好的学习方式是直接开始，被压得喘不过气来，完全不知道自己在做什么。那样的话，你的大脑就会渴望学习，并能把学到的东西应用到切实可见的事物上。</p><p>我现在就可以告诉你，如果你没有一边学习一边积极地构建实践，那你从课程中学习就是在浪费时间。</p><p>每个人都能看一个视频，了解顶尖CEO到底是如何在创纪录的时间内建立一个十亿美元级别企业的，但实际上有多少人复制了这种成功？如果真像跟着分步教程操作那么简单（我在跟你们说话，那些希望这些信件更短且“直奔主题”的人），那大家现在都已经是亿万富翁了。</p><p>你需要同时具备在正确时间的<em>正确想法</em>，以及经验。</p><p>经验，经验，经验。</p><p>经验为王。</p><p>经验<em>不仅</em>是进步。</p><p>经验是由失败的频率决定的。</p><p>就像在电子游戏中打Boss。</p><p>你试了一次，被虐得体无完肤。</p><p>你稍微改变了策略，再试一次，还是输了。</p><p>你有了一个更好的主意，试了一下，<em>几乎</em>赢了。</p><p>然后你又连输了5次，开始怀疑自己是不是疯了。</p><p>你关掉游戏，去户外透透气。</p><p>紧接着，最完美的点子在你最意想不到的时候撞进你的大脑。你启动游戏，带着自信出击，轻松拿下。</p><p>每当你对自己的进度感到气馁时，记住这个过程。这都是一场游戏。</p><p>你应该这样去学习：</p><ul><li><strong>你需要一个目标来构建你的学习框架。</strong> 在这种情况下，目标就是建立受众并赚取收入。如果你没有朝着这个方向取得进展，那你就需要继续学习、测试和失败，直到你看到粉丝和收入增长。如果没增长，那就是技能问题。</li><li><strong>你需要从你已知的东西开始。</strong> 很明显，你需要在社交媒体上建立个人资料，定期发布内容，以及找到某种方法让看到内容的人为你买单。</li><li><strong>你需要有源源不断的主意来改进你的流程。</strong> 购买课程去研究别人的系统，并拿它们做实验。让某种形式的灵感每天进入你的大脑。</li><li><strong>当你遇到问题时，你需要特定的信息。</strong> 在你遇到问题时再去研究如何解决，而不是提前研究。比如如何开办时事通讯、如何设计头像或如何建一个网站。</li></ul><p>我从来没有专门花时间去学某项特定的技能，比如电子邮件营销或平面设计。</p><p>我总是先启动一个项目，准确去查找到达目标所需要知道的东西，然后重复这个过程。</p><p>现在，我掌握了一堆真正能带来结果的技能栈。到这种地步，甚至很难将它们视为一项项独立的技能了，无非就是在实现了那么多目标之后，懂得了如何达成一个特定的目标。</p><h3 id="_2-选择你精通的领域" tabindex="-1">2) 选择你精通的领域 <a class="header-anchor" href="#_2-选择你精通的领域" aria-label="Permalink to &quot;2) 选择你精通的领域&quot;">​</a></h3><p>让我们回到专业化全才（specialized generalism）这个话题。</p><p><img src="'+e+'" alt=""></p><p>创造了电子游戏《半条命》（Half-Life）的公司Valve曾提到，他们的公司由“T型”人才组成。</p><p>即既是全才又是专才的人。“T”的顶部代表精通广泛且有价值的事务。底部则代表在某个狭窄的研究领域名列前茅。</p><p>这之所以行得通，是因为当你精通某件事时，你会在许多领域变得有价值，但如果你在那些领域没有经验，你通常意识不到自己的技能能如何与它们产生交集。</p><p>我敢说我很擅长写作，不是因为我的语法或结构最好，而是因为我的其他技能帮助我实现了写作的主要目标：朝积极的方向激发行为转变。</p><p>当我从另一个角度考虑时，写作并不是我的核心技能。实际上，在几个朋友向我指出来之前，我都不知道我的核心技能是什么。</p><p>我非常擅长在脑子里同时容纳许多想法。我通常能梳理通整个战略、商业模式或其他复杂的话题，并注意到所有的陷阱和问题，只要有足够的时间，我就能想出一个制胜的解决方案。</p><p>但也许正是写作促成了这一点。所以归根结底，去学很多东西，去构建很多东西就对了。</p><p>如果让我重新解释什么是“T”型人才或专业化全才，那就是：</p><p><em>一个能够且愿意为了某个项目、目标或愿景去学习任何兴趣或技能的人。他们明白使命是什么，自己在其中的角色，以及要实现它需要学什么。这在那些不允许自主发挥、或者不允许打破重复性常规任务的企业岗位或工作中，是非常难以做到的。</em></p><p>你的认知覆盖面越大，你能解决的问题就越有价值。你不再与某个细分领域的专家竞争，而是开始解决别人无法解决的问题。</p><p>作为创作者起步，你需要有价值可以分享。你需要内容点子。你需要有能变现的东西。你需要给人们一个关注并付费给你的理由。</p><p>我不认为把这些东西写下来、放进特定的框框里会有多大帮助。</p><p>相反，我建议你写出2-3个你非常感兴趣的大方向话题，从那里开始。</p><p>这可以是特定技能，比如营销和编程，也可以是某些兴趣，比如自我提升或健身。只要它们与能提升你自己和他人的目标和项目相契合，你就没问题。</p><p>制造噪音，找到信号。</p><p>开始就你觉得有趣、对你的生活有价值的东西去写作和创作。你会慢慢发现自己擅长什么，或者想要擅长什么。</p><h3 id="_3-先学会正确的技能-习惯" tabindex="-1">3）先学会正确的技能（习惯） <a class="header-anchor" href="#_3-先学会正确的技能-习惯" aria-label="Permalink to &quot;3）先学会正确的技能（习惯）&quot;">​</a></h3><p>除了你目前的技能或兴趣之外，还有一些特定的技能，你需要学会，才能让你的创作者事业获得成功。</p><ul><li><strong>写作</strong> —— 你需要写帖子、邮件、视频脚本、落地页、课程、私信和课程材料。我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写作者</a>中教这个。</li><li><strong>演讲</strong> —— 传播想法的另一种方式，通常在先写作的基础上得到强化。</li><li><strong>营销</strong> —— 理解你的文字或言语如何触达人们、在哪里触达他们、对他们产生了怎样的影响，以及这种影响的结果是什么（他们是否会朝着你引导的目标行动或参与？）</li><li><strong>销售</strong> —— 用一种能让人们把你提供的东西感知为有价值的方式去打造你的文字。销售是艺术家挨饿的解药。</li></ul><p>如果把这些都结合起来，其实就是<em>说服力</em>。这就是你需要学习的技能。我们会在下周的信里讨论它。</p><p>这些与其说是技能，更是习惯。它们是成功人士的习惯。你去找任何一个创作者，或者说任何一个成功的人，我可以保证他们中的大多数（如果他们仍在经营这个业务）每天都在写作。这是一种习惯。是一种生活方式。是通往成功的主要杠杆。</p><p>如果你不写，你到底要怎么产出任何东西呢？</p><p>写作是沟通的基础媒介。</p><p>写作是有形化的思考，如果你的想法一直留在脑子里，你不会有任何进展。</p><p>写作是你构建并传播你想法的方式。</p><p>那么，营销和销售在哪里发挥作用呢？</p><p>它们塑造你<em>如何</em>写作和表达。</p><p>如果你只是随心所欲地写，不管方式方法，你最终会成为一个没有读者的作者，或者一个没有用户的创业公司。</p><p>这并不会剥夺你的创造力，因为创造力正是在你所设定的限制之内发生的。事实上，要在保持真实的<em>同时</em>以最有影响力的方式传达你的信息，需要更多的创造力。</p><p>举个例子，每天用4小时经营一个企业、同时不牺牲你的关系或健康，比起经营一个企业却忘记了生活中一切重要的事情，需要更多的创造力。前者也会带来更令人满足的结果（以及更多的知识/经验）。</p><p>最好的营销和销售是察觉不到的。最有创造力的人会让它看起来毫不费力。</p><h3 id="_4-专注于流量" tabindex="-1">4）专注于流量 <a class="header-anchor" href="#_4-专注于流量" aria-label="Permalink to &quot;4）专注于流量&quot;">​</a></h3><p>我在初学者身上看到的最大错误是，他们根本不理解商业。</p><p><strong>规则1）</strong>产生流量。</p><p><strong>规则2）</strong>销售一个产品。</p><p><strong>规则3）</strong>根据你理想的生活方式，优化连接1和2的系统。</p><p>我不知道人们脑子里在想什么，但如果你的受众没有在增长……<em>那你就是哪里做错了。</em>如果你没有产生销售……<em>那你就是哪里做错了。</em></p><p>这意味着什么？</p><p>这意味着有问题存在。</p><p>而既然你是一个创业者，找出问题并通过实验和学习去解决它，就是你的工作。</p><p>我之前已经给出过如何掌控你在社交媒体上增长的具体策略，讲得有点太细了。你可以在这篇文章里找到：<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">如何真正在社交媒体上增长</a>。</p><p>现在，你只需要明白，你需要不断尝试各种方法，直到某个方法奏效，然后把它系统化成你深度工作时段里的一个习惯，然后终生继续实验下去。</p><p>这可能是回复大账号的评论、付费增长、建立人脉网络，或是破解算法。每个人都会大声争论哪种方法更好，哪种方法不道德，哪种方法很糟糕。如果你听他们的，你可能会把心思关闭在那个本可以对你有效的方法上。然后，你就退出，说这是个庞氏骗局，哈哈。</p><p>什么都试试，看什么能坚持下去。</p><p>一段活得精彩、而非仅仅苟活的人生，是一系列实验组成的。</p><h3 id="_5-卖什么-按什么顺序卖" tabindex="-1">5）卖什么，按什么顺序卖 <a class="header-anchor" href="#_5-卖什么-按什么顺序卖" aria-label="Permalink to &quot;5）卖什么，按什么顺序卖&quot;">​</a></h3><p>我之前也多次谈过这个话题。</p><p>在<a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">一人企业从0到100万美元</a>一文中，我详细拆解了如果你想在少工作的同时赚更多钱（而不雇人），创意工作必须如何演变。</p><p>在我看来，你能做的最好的事情如下：</p><p><strong>1）打造一个极简报价</strong></p><p>这是我提出的一个新概念，我会在另一封信中展开讲。</p><p>简而言之，一个极简报价包含：</p><ol><li>你能帮人解决什么</li><li>一个付款链接</li><li>可选项：给暖流量准备的一份问卷</li></ol><p>没有落地页。没有logo。没有有限责任公司。除了跟你的受众聊他们的目标、并提出用钱换取帮助之外，什么都不需要。</p><p>当你还没有庞大的受众群体时，你的大部分销售都会来自私信。</p><p>你写针对人们痛点的内容。</p><p>你回复人们的评论，把对话引到私信里。</p><p>你进一步问他们的目标，并给一些免费的指导（这会为你自己建立起人脉网络）。</p><p>你提到你可以在接下来的几周里<em>教</em>他们（并说明这需要花点钱，但不会太多）。你帮他们用你已经学到的技能/兴趣实现他们的目标。你测试什么真正能带来结果，并完善你自己的体系。然后你就可以把它打包起来，在步骤2之外收更高的费用。</p><p>换句话说，你要学会随手就能创造报价。</p><p>实际上没有人需要落地页才能成交客户。尤其是当你与对方的私信本身就发挥着落地页的作用时。它让对方意识到自己的痛点，并把你定位为解决方案。</p><p>你创建的问卷会问他们的目标是什么，以及是什么阻碍他们实现目标。你会把它放在你的简介里，如果你写邮件的话也放在邮件里。这是一种让人们表达出想和你合作的意愿的方式，适用于你不是主动私信对方的情况（一定要记得问对方要社交账号，这样你之后可以私信他们）。</p><p>我就是这样从自由职业网页设计转型成为社交媒体企业（也就是创作者）的“营销顾问”的。我和他们聊天，提到我可以帮他们更快增长（更多流量）、卖得更多——你知道的，不管对方是不是创作者，这都是你能帮企业的唯二两件事。而如果他们没有可卖的东西，我就帮他们打造一个报价。</p><p>记住，定位。</p><p><strong>2）可选项：把它变成一个服务型企业</strong></p><p>如果能回到过去，我会少关注服务，多关注类似训练营式课程的东西。</p><p>而且，我作为创作者创造的第一个东西是一个网页设计课程，不是营销咨询服务。那个是后来才出现的。</p><p>现在我认识了很多受人尊敬的人，比如大卫·佩雷尔（David Perell）和迪基·布什（Dickie Bush），他们都是从一个训练营式课程起步的（而且赚得比我多得多），我认为那才是最优的选择。</p><p>不过，如果你的账号没有逐月增长，这个方法可能不会很有效。但如果你没有在增长，那你面临的问题比“该卖什么报价”要大得多。你需要先解决那个问题。</p><p>但如果你真的坚持要这么做，就把你的极简报价转变成一个服务型企业。自由职业或者做教练。拿你的技能和兴趣，创建一个能达成特定结果的体系，然后开始研究如何获取潜在客户，并在销售电话中促成成交。</p><p><strong>3）把它转变成一个训练营式课程</strong></p><p>注意我用的词是“转变”成训练营式课程。</p><p>服务型企业通常非常具体，针对更高阶的问题。</p><p>而对于训练营式课程和其他产品，你的目标是以更低的价格让<em>更多人</em>加入进来（但要有一套交付结构，让你能省下更多时间，摆脱客户工作）。</p><p>同时，你也可以给训练营式课程定很高的价格，只招收较少的人。大卫·佩雷尔的课程收费高达7000美元以上。那比大多数服务型企业还高。到那个程度，你其实就是把它当成一个服务型企业来运作，一路上做更多人工外联去促成学员成交。</p><p>对于训练营式课程，你通常会更偏向初学者水平，这样才能帮到更多人。你通常是在用你的主要技能或兴趣，帮他们获得一个想要的结果——就像我教人们如何写作，以便为他们喜欢做的工作建立受众一样。</p><p>顺便说一句，训练营式课程其实就是一个有结构的课程，你在其中引导人们前行。</p><p>你设定一个开始日期和结束日期。</p><p>你有课程大纲。</p><p>你每周有1-2次通话，用来答疑并讲解材料。</p><p>有时你还会有一个社群，供大家参与其中。</p><p><strong>4）把它转变成一个数字产品</strong></p><p>如果你想从一个数字产品起步，我在我的营销/产品开发课程<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">心智变现</a>中教你怎么做。</p><p>既然你现在已经清楚地知道自己在做什么，并且有了成果，就把你所教的一部分内容<em>转变</em>成一个数字产品。</p><p>最好的起点是你的主要技能或兴趣。</p><p>别把它搞得太复杂。</p><p>用你自己希望被触达的方式，去教这个技能或兴趣。</p><p>包含项目、模板、任务，以及一套涵盖人们需要知道的一切、以达成理想最终结果的课程大纲。</p><p><strong>5）打造一个你想要、但市面上还不存在的东西</strong></p><p>到这个阶段，你已经拥有了受众、一个盈利的企业，以及可以投入到一种新型企业的多余现金流。</p><p>（或者，你可以通过雇更多人，继续扩大你已经开始的服务型企业。）</p><p>你知道你的受众想要什么、需要什么。</p><p>你可以用一个数字产品或软件，去补充你目前的产品线。</p><p>这类似于我们为什么要打造Kortex（并且<a href="https://kortex.co/" target="_blank" rel="noreferrer">即将向候补名单上的人推出！</a>）。</p><p>Notion感觉臃肿，写起来也不舒服。</p><p>我没有一个好方法来组织我所有的想法。</p><p>大多数其他“第二大脑”应用，对普通人来说都太令人困惑了。</p><p>所以我们创造了一个更好的东西。</p><p>这对你来说并非不可能。</p><p>当你拥有社会资本（相对于风险资本）时，到那个阶段，你真的可以打造任何你想要的东西。</p><p>所以，无论你目前在创作者旅程的哪个阶段，我希望这篇文章对你有帮助，也祝你一切顺利。</p><p>感谢阅读。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/the-creator-economy-is-a-giant-ponzi-scheme">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',238))])}const x=r(h,[["render",c]]);export{q as __pageData,x as default};
